import React, { useState, useEffect, useCallback } from 'react';
import { Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const authHeaders = () => ({
  'Content-Type': 'application/json',
  Authorization: `Bearer ${localStorage.getItem('adminToken') || ''}`,
});

const AdminDashboard: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const [stats, setStats] = useState<any>(null);
  const [applications, setApplications] = useState<any[]>([]);
  const [vouchers, setVouchers] = useState<any[]>([]);
  const [loadingApps, setLoadingApps] = useState(false);
  const [loadingVouchers, setLoadingVouchers] = useState(false);
  const [appFilter, setAppFilter] = useState({ type: '', status: '', search: '' });

  const fetchStats = useCallback(async () => {
    try {
      const res = await fetch(`${API}/api/admin/dashboard/stats`, { headers: authHeaders() });
      const data = await res.json();
      if (data.success) setStats(data.stats);
    } catch { /* silent */ }
  }, []);

  const fetchApplications = useCallback(async () => {
    setLoadingApps(true);
    try {
      const params = new URLSearchParams();
      if (appFilter.type)   params.set('type',   appFilter.type);
      if (appFilter.status) params.set('status', appFilter.status);
      if (appFilter.search) params.set('search', appFilter.search);
      const res = await fetch(`${API}/api/admin/applications?${params}`, { headers: authHeaders() });
      const data = await res.json();
      if (data.success) setApplications(data.applications);
    } catch { /* silent */ } finally { setLoadingApps(false); }
  }, [appFilter]);

  const fetchVouchers = useCallback(async () => {
    setLoadingVouchers(true);
    try {
      const res = await fetch(`${API}/api/admin/vouchers`, { headers: authHeaders() });
      const data = await res.json();
      if (data.success) setVouchers(data.vouchers);
    } catch { /* silent */ } finally { setLoadingVouchers(false); }
  }, []);

  useEffect(() => { fetchStats(); }, [fetchStats]);

  useEffect(() => {
    if (location.pathname.includes('/applications')) fetchApplications();
    if (location.pathname.includes('/vouchers'))     fetchVouchers();
  }, [location.pathname, fetchApplications, fetchVouchers]);

  const approveApplication = async (appId: string) => {
    if (!window.confirm(`Approve application ${appId}?`)) return;
    try {
      const res = await fetch(`${API}/api/admin/applications/${appId}/approve`, {
        method: 'POST', headers: authHeaders(),
      });
      const data = await res.json();
      alert(data.message || 'Done');
      fetchApplications();
      fetchStats();
    } catch { alert('Error approving application'); }
  };

  const rejectApplication = async (appId: string) => {
    const reason = window.prompt('Reason for rejection (optional):');
    if (reason === null) return;
    try {
      const res = await fetch(`${API}/api/admin/applications/${appId}/reject`, {
        method: 'POST',
        headers: authHeaders(),
        body: JSON.stringify({ reason }),
      });
      const data = await res.json();
      alert(data.message || 'Done');
      fetchApplications();
      fetchStats();
    } catch { alert('Error rejecting application'); }
  };

  const resendVoucher = async (voucher: any) => {
    alert(`Resend feature: voucher ${voucher.voucher_code} to ${voucher.email}`);
  };

  const handleLogout = () => {
    localStorage.removeItem('adminToken');
    localStorage.removeItem('adminUser');
    navigate('/admin/login');
  };

  const navItems = [
    { to: '/admin', label: 'Overview', exact: true },
    { to: '/admin/applications', label: 'Applications' },
    { to: '/admin/vouchers', label: 'Vouchers' },
  ];

  const isActive = (to: string, exact?: boolean) =>
    exact ? location.pathname === to : location.pathname.startsWith(to);

  return (
    <div>
      <header className="header">
        <div className="header-content">
          <div className="logo-section">
            <img src="http://wuc.edu.gh/wp-content/uploads/2025/05/WC-logo-on-white-1.jpg" alt="WUC Logo" />
            <div>
              <h1>WUC Administration</h1>
              <span className="logo-sub">Admissions Management</span>
            </div>
          </div>
          <nav>
            <ul className="nav-links">
              {navItems.map(({ to, label, exact }) => (
                <li key={to}>
                  <Link to={to} style={isActive(to, exact) ? { background: 'rgba(255,255,255,0.18)', color: 'white' } : {}}>
                    {label}
                  </Link>
                </li>
              ))}
              <li>
                <Link to="/" style={{ color: 'rgba(255,255,255,0.55)', fontSize: '0.8rem' }}>Exit ↗</Link>
              </li>
              <li>
                <button onClick={handleLogout} style={{ background: 'rgba(255,255,255,0.12)', color: 'rgba(255,255,255,0.8)', border: 'none', borderRadius: 'var(--radius-xs)', padding: '0.45rem 0.875rem', fontSize: '0.8rem', cursor: 'pointer', fontWeight: 500 }}>
                  Logout
                </button>
              </li>
            </ul>
          </nav>
        </div>
      </header>

      <div className="container">
        <Routes>
          {/* Overview */}
          <Route path="/" element={
            <div>
              <div style={{ marginBottom: '1.5rem' }}>
                <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)', letterSpacing: '-0.01em' }}>
                  Dashboard Overview
                </h2>
                <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                  Current admissions cycle summary
                </p>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1.25rem', marginBottom: '2rem' }}>
                <div className="stat-card blue">
                  <div className="stat-label">Total Applications</div>
                  <div className="stat-value">{stats?.totalApplications ?? '—'}</div>
                  <div className="stat-sub">Regular: {stats?.regularApplications ?? 0} · Top-Up: {stats?.topupApplications ?? 0}</div>
                </div>
                <div className="stat-card amber">
                  <div className="stat-label">Pending Review</div>
                  <div className="stat-value">{stats?.pendingApplications ?? '—'}</div>
                  <div className="stat-sub">Awaiting decision</div>
                </div>
                <div className="stat-card green">
                  <div className="stat-label">Approved</div>
                  <div className="stat-value">{stats?.approvedApplications ?? '—'}</div>
                  <div className="stat-sub">Admission letters sent</div>
                </div>
                <div className="stat-card purple">
                  <div className="stat-label">Vouchers Sold</div>
                  <div className="stat-value">{stats?.totalVouchers ?? '—'}</div>
                  <div className="stat-sub">{stats?.usedVouchers ?? 0} used</div>
                </div>
              </div>

              <div className="card">
                <h3 className="section-title">Quick Actions</h3>
                <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
                  <Link to="/admin/applications"><button className="btn btn-primary">Review Applications</button></Link>
                  <Link to="/admin/vouchers"><button className="btn btn-ghost">Manage Vouchers</button></Link>
                </div>
              </div>
            </div>
          } />

          {/* Applications */}
          <Route path="/applications" element={
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
                <div>
                  <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)' }}>Applications</h2>
                  <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                    {applications.length} shown
                  </p>
                </div>
                <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                  <select value={appFilter.type} onChange={e => setAppFilter(f => ({ ...f, type: e.target.value }))}
                    style={{ padding: '0.4rem 0.75rem', borderRadius: 'var(--radius-sm)', border: '1.5px solid var(--border)', fontSize: '0.8125rem', background: 'var(--surface)' }}>
                    <option value="">All Types</option>
                    <option value="regular">Regular</option>
                    <option value="topup">Top-Up</option>
                  </select>
                  <select value={appFilter.status} onChange={e => setAppFilter(f => ({ ...f, status: e.target.value }))}
                    style={{ padding: '0.4rem 0.75rem', borderRadius: 'var(--radius-sm)', border: '1.5px solid var(--border)', fontSize: '0.8125rem', background: 'var(--surface)' }}>
                    <option value="">All Statuses</option>
                    <option value="pending">Pending</option>
                    <option value="approved">Approved</option>
                    <option value="rejected">Rejected</option>
                  </select>
                  <input type="text" placeholder="Search name / email / ID…" value={appFilter.search}
                    onChange={e => setAppFilter(f => ({ ...f, search: e.target.value }))}
                    style={{ padding: '0.4rem 0.75rem', borderRadius: 'var(--radius-sm)', border: '1.5px solid var(--border)', fontSize: '0.8125rem', minWidth: '200px' }} />
                  <button onClick={fetchApplications} className="btn btn-primary btn-sm">Search</button>
                </div>
              </div>
              {loadingApps ? (
                <div className="spinner" />
              ) : (
                <div className="table-wrap">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>ID</th>
                        <th>Name</th>
                        <th>Email</th>
                        <th>Type</th>
                        <th>Enrollment</th>
                        <th>Status</th>
                        <th>Date</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {applications.length === 0 && (
                        <tr><td colSpan={8} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '2rem' }}>No applications found</td></tr>
                      )}
                      {applications.map(app => (
                        <tr key={app.application_id}>
                          <td style={{ fontFamily: 'monospace', fontSize: '0.8125rem', color: 'var(--text-secondary)' }}>{app.application_id}</td>
                          <td style={{ fontWeight: 600 }}>{app.first_name} {app.last_name}</td>
                          <td style={{ color: 'var(--text-secondary)', fontSize: '0.8125rem' }}>{app.email}</td>
                          <td>
                            <span className={`badge ${app.application_type === 'topup' ? 'badge-warning' : 'badge-info'}`}>
                              {app.application_type === 'topup' ? 'Top-Up' : 'Regular'}
                            </span>
                          </td>
                          <td style={{ fontSize: '0.8125rem', color: 'var(--text-secondary)' }}>{app.enrollment_option || '—'}</td>
                          <td>
                            <span className={`badge ${app.status === 'approved' ? 'badge-success' : app.status === 'rejected' ? 'badge-danger' : 'badge-warning'}`}>
                              {app.status}
                            </span>
                          </td>
                          <td style={{ color: 'var(--text-muted)', fontSize: '0.8125rem' }}>
                            {app.submitted_at ? new Date(app.submitted_at).toLocaleDateString() : '—'}
                          </td>
                          <td>
                            <div style={{ display: 'flex', gap: '0.375rem' }}>
                              {app.status === 'pending' && (
                                <>
                                  <button onClick={() => approveApplication(app.application_id)} className="btn btn-success btn-sm">Approve</button>
                                  <button onClick={() => rejectApplication(app.application_id)} className="btn btn-danger btn-sm">Reject</button>
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          } />

          {/* Vouchers */}
          <Route path="/vouchers" element={
            <div>
              <div style={{ marginBottom: '1.5rem' }}>
                <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)' }}>Vouchers</h2>
                <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                  {vouchers.length} total
                </p>
              </div>
              {loadingVouchers ? (
                <div className="spinner" />
              ) : (
                <div className="table-wrap">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Voucher Code</th>
                        <th>Name</th>
                        <th>Email</th>
                        <th>Phone</th>
                        <th>Status</th>
                        <th>Expires</th>
                        <th>Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {vouchers.length === 0 && (
                        <tr><td colSpan={7} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '2rem' }}>No vouchers found</td></tr>
                      )}
                      {vouchers.map(v => (
                        <tr key={v.voucher_code}>
                          <td style={{ fontFamily: 'monospace', fontWeight: 700, letterSpacing: '0.04em', fontSize: '0.875rem' }}>{v.voucher_code}</td>
                          <td style={{ fontWeight: 500 }}>{v.first_name} {v.last_name}</td>
                          <td style={{ color: 'var(--text-secondary)', fontSize: '0.8125rem' }}>{v.email}</td>
                          <td style={{ color: 'var(--text-secondary)', fontSize: '0.8125rem' }}>{v.phone}</td>
                          <td>
                            <span className={`badge ${v.status === 'used' ? 'badge-neutral' : v.status === 'expired' ? 'badge-danger' : 'badge-success'}`}>
                              {v.status}
                            </span>
                          </td>
                          <td style={{ color: 'var(--text-muted)', fontSize: '0.8125rem' }}>
                            {v.expires_at ? new Date(v.expires_at).toLocaleDateString() : '—'}
                          </td>
                          <td>
                            <button onClick={() => resendVoucher(v)} className="btn btn-ghost btn-sm">Resend</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          } />
        </Routes>
      </div>
    </div>
  );
};

export default AdminDashboard;
